import React, { Component } from "react";
import NavBar from "./components/navbar/NavBar";
import GlobalStyles from "./styles/Global";
import Slideshow from './components/slideshow/SlideShow';
import Info from './components/Info';
import About from './components/About';
import Services from './components/Services';
import References from './components/References';

class App extends Component {

  constructor(props) {
    super(props)
    this.infoSection = React.createRef();
    this.aboutSection = React.createRef();
    this.servicesSection = React.createRef();
    this.scrollToContent = this.scrollToContent.bind(this);
  }

  scrollToContent(content) {
    switch (content) {
      case 'info':
        this.infoSection.current.scrollIntoView({ behavior: 'smooth' });
        break;
      case 'about':
        this.infoSection.current.scrollIntoView({ behavior: 'smooth' });
        break;
      case 'services':
        this.infoSection.current.scrollIntoView({ behavior: 'smooth' });
    }
  }

  render() {

    return (
      <>
        <NavBar goTo={this.scrollToContent} />
        <Slideshow />
        <Info ref={this.infoSection} />
        <About ref={this.aboutSection} />
        <Services ref={this.servicesSection} />
        <References />
        <GlobalStyles />
      </>
    );
  }
}

export default App;
